-- Film-service catalog snapshot generated from the live development database on 2026-08-10.
-- Runtime outbox rows are intentionally excluded: replaying historical integration events is not seed data.
-- The marker prevents spring.sql.init.mode=always from resurrecting episodes deleted after first initialization.
-- All episode titles are Vietnamese with diacritics. Episode video_file_id stays NULL
-- until the confirmed Vagabond source files are uploaded and their real file IDs are provided.

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
CREATE TABLE IF NOT EXISTS `film_seed_metadata` (`seed_key` varchar(100) NOT NULL, `applied_at` datetime(6) NOT NULL, PRIMARY KEY (`seed_key`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
SET @film_seed_required = NOT EXISTS (SELECT 1 FROM `film_seed_metadata` WHERE `seed_key` = 'catalog-2026-08-10');


-- Fresh search-index events. Historical runtime outbox rows are excluded above; these 27 current snapshots are safe to publish once.
SELECT CONCAT('seed-film-sync-', f.`id`), f.`id`, CURRENT_TIMESTAMP(6),
       JSON_OBJECT('id', f.`id`, 'title', f.`title`, 'thumbnailUrl', f.`thumbnail_url`, 'thumbnailFileId', f.`thumbnail_file_id`, 'averageRating', f.`average_rating`, 'ratingCount', f.`rating_count`, 'followCount', f.`follow_count`, 'episodeCount', f.`episode_count`, 'season', f.`season`, 'status', f.`status`, 'lastUpdate', DATE_FORMAT(f.`last_update`, '%Y-%m-%dT%H:%i:%s.%fZ')),
       'film.sync'
FROM `films` f WHERE @film_seed_required = 1;

SET FOREIGN_KEY_CHECKS = 1;
